const DB_NAME='atsfy-finance-local'; const DB_VERSION=2;
const STORES=['projects','invoices','payments','expenses','clients','purchase_orders','settings'];
function openDB():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;STORES.forEach(name=>{if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:'id'})})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function dbAll(store:string):Promise<Row[]>{const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly');const req=tx.objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close()})}
async function dbPut(store:string,value:Row):Promise<void>{const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function dbDelete(store:string,id:string):Promise<void>{const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function dbClear(store:string):Promise<void>{const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).clear();tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function dbRestore(records:Record<string,Row[]>):Promise<void>{const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORES,'readwrite');for(const store of STORES){const objectStore=tx.objectStore(store);objectStore.clear();for(const row of (records[store]||[]))objectStore.put(row)}tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||new Error('Restore transaction was aborted.'))}})}
async function pinHash(pin:string){const bytes=new TextEncoder().encode(pin);const digest=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('')}
const round2=(value:number)=>Math.round((value+Number.EPSILON)*100)/100;
const money=(v:number|string|undefined)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(v||0));
const today=()=>{const date=new Date();date.setMinutes(date.getMinutes()-date.getTimezoneOffset());return date.toISOString().slice(0,10)};
const financialYearStart=()=>{const date=new Date();return date.getMonth()>=3?date.getFullYear():date.getFullYear()-1};
const financialYearLabel=()=>{const start=financialYearStart();return start+'–'+String(start+1).slice(-2)};
