const nav=[['dashboard','Overview',LayoutDashboard],['projects','Projects',FolderKanban],['clients','Clients',Wallet],['invoices','Invoices',FileText],['payments','Payments',Wallet],['expenses','Expenses',Receipt],['reports','Reports',ChartNoAxesCombined],['purchase_orders','Purchase Orders',FileText],['settings','Settings',Settings]] as const;

function FinancialTrendChart({payments,expenses}:{payments:Row[];expenses:Row[]}){
 const months=useMemo(()=>{const now=new Date();const buckets=Array.from({length:6},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-5+i,1);return {key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,label:d.toLocaleDateString('en-IN',{month:'short'}),received:0,expenses:0}});const byKey=new Map(buckets.map(x=>[x.key,x]));payments.filter(x=>x.status==='received').forEach(x=>{const raw=x.payment_date||x.created_at;if(!raw)return;const key=String(raw).slice(0,7);const bucket=byKey.get(key);if(bucket)bucket.received+=Number(x.amount||0)});expenses.forEach(x=>{const raw=x.expense_date||x.created_at;if(!raw)return;const key=String(raw).slice(0,7);const bucket=byKey.get(key);if(bucket)bucket.expenses+=Number(x.total_amount||0)});return buckets},[payments,expenses]);
 const max=Math.max(1,...months.flatMap(x=>[x.received,x.expenses]));const hasData=months.some(x=>x.received>0||x.expenses>0);
 return <div className="panel cashflow-panel"><div className="panel-head"><div><h3>Cash flow trend</h3><p>Monthly receipts versus recorded expenses · last 6 months</p></div><span className="chart-period">LIVE FROM RECORDS</span></div>{hasData?<><div className="cashflow-legend"><span><i className="legend-received"/>Payments received</span><span><i className="legend-expenses"/>Expenses</span></div><div className="cashflow-plot">{months.map(m=><div className="cashflow-month" key={m.key}><div className="cashflow-bars"><div className="cashflow-bar received" style={{height:`${Math.max(m.received>0?3:0,m.received/max*100)}%`}} title={`Received: ${money(m.received)}`}/><div className="cashflow-bar expenses" style={{height:`${Math.max(m.expenses>0?3:0,m.expenses/max*100)}%`}} title={`Expenses: ${money(m.expenses)}`}/></div><span>{m.label}</span></div>)}</div><div className="cashflow-foot"><span>Receipts: <b>{money(months.reduce((s,m)=>s+m.received,0))}</b></span><span>Expenses: <b>{money(months.reduce((s,m)=>s+m.expenses,0))}</b></span></div></>:<div className="chart-empty">Your monthly trend will appear here as payments and expenses are recorded.</div>}</div>
}

